21	/**
22	 * Ponto único de conversão de exceções em respostas no formato de erro do contrato da API.
23	 */
24	@RestControllerAdvice
25	public class ApiExceptionHandler {
26	
27	    private static final Logger log = LoggerFactory.getLogger(ApiExceptionHandler.class);
28	    private static final MediaType JSON_UTF8 = new MediaType(MediaType.APPLICATION_JSON, StandardCharsets.UTF_8);
29	
30	    @ExceptionHandler(ApiException.class)
31	    ResponseEntity<ErrorResponse> handleApiException(ApiException exception) {
32	        return respond(exception.status(), ErrorResponse.of(exception.field(), exception.detail()));
33	    }
34	
35	    @ExceptionHandler(MethodArgumentNotValidException.class)
36	    ResponseEntity<ErrorResponse> handleValidation(MethodArgumentNotValidException exception) {
37	        Map<String, List<String>> errors = new TreeMap<>();
38	        for (FieldError fieldError : exception.getBindingResult().getFieldErrors()) {
39	            errors.computeIfAbsent(simpleFieldName(fieldError.getField()), key -> new ArrayList<>())
40	                    .add(fieldError.getDefaultMessage());
41	        }
42	        if (errors.isEmpty()) {
43	            errors.put("body", List.of("is invalid"));
44	        }
45	        return respond(HttpStatus.UNPROCESSABLE_CONTENT, new ErrorResponse(errors));
46	    }
47	
48	    @ExceptionHandler(HttpMessageNotReadableException.class)
49	    ResponseEntity<ErrorResponse> handleUnreadableBody(HttpMessageNotReadableException exception) {
50	        log.debug("Corpo da requisição ilegível", exception);
51	        return respond(HttpStatus.UNPROCESSABLE_CONTENT, ErrorResponse.of("body", "can't be empty or malformed"));
52	    }
53	
54	    private static ResponseEntity<ErrorResponse> respond(HttpStatusCode status, ErrorResponse body) {
55	        return ResponseEntity.status(status).contentType(JSON_UTF8).body(body);
56	    }
57	
58	    /** Converte {@code user.email} em {@code email}: o envelope {@code user} não interessa ao cliente. */
59	    private static String simpleFieldName(String path) {
60	        return path.substring(path.lastIndexOf('.') + 1);
61	    }
62	}
